from hesap import calistir

def test():
    test_cases = [
        ("x = 5\ny = 10\nx + y", 15),
        ("a = 2 ** 3 ** 2", 512),
        ("-2 ** 2", -4),
        ("abs(-5)", 5),
        ("min(1, 2, 3)", 1),
        ("max(1, 2, 3)", 3),
        ("x = 10 / 4\nx", 2.5),
        ("x = 10 % 3\nx", 1),
    ]

    for i, (prog, expected) in enumerate(test_cases):
        try:
            res = calistir(prog)
            assert res == expected, f"Test {i} failed: expected {expected}, got {res}"
            print(f"Test {i} passed")
        except Exception as e:
            print(f"Test {i} failed with error: {e}")

    # Error cases
    error_cases = [
        ("x = 5 +", SyntaxError),
        ("(1 + 2", SyntaxError),
        ("3 4", SyntaxError),
        ("2 $ 3", SyntaxError),
        ("y = z + 1", NameError),
    ]

    for i, (prog, error_type) in enumerate(error_cases):
        try:
            calistir(prog)
            print(f"Error Test {i} failed: expected {error_type.__name__}, got {type(calistir(prog)).__name__}") # This is wrong logic for testing errors, let's fix it below.
        except Exception as e:
            if not isinstance(e, error_type):
                print(f"Error Test {i} failed: expected {error_type.__name__}, got {type(e).__name__}")
            else:
                print(f"Error Test {i} passed")

# Corrected Error Testing logic
def test_errors():
    error_cases = [
        ("x = 5 +", SyntaxError),
        ("(1 + 2", SyntaxError),
        ("3 4", SyntaxError),
        ("2 $ 3", SyntaxError),
        ("y = z + 1", NameError),
        ("1 / 0", ZeroDivisionError),
    ]

    for i, (prog, error_type) in enumerate(error_cases):
        try:
            calistir(prog)
            print(f"Error Test {i} failed: expected {error_type.__name__}")
        except Exception as e:
            if isinstance(e, error_type):
                print(f"Error Test {i} passed")
            else:
                print(f"Error Test {i} failed: expected {error_type.__name__}, got {type(e).__name__}")

test()
test_errors()

