{"content":"import re

class SyntaxError(Exception):
    pass

class NameError(Exception):
    pass

class ZeroDivisionError(Exception):
    pass

class Calculator:
    def __init__(self):
        self.variables = {}

    def tokenize(self, text):
        tokens = []
        i = 0
        while i < len(text):
            char = text[i]
            if char.isspace():
                i += 1
                continue
            if char == '#':
                break
            if char in '()+-*/%=':
                tokens.append(('SYMBOL', char))
                i += 1
            elif char == '*':
                if i + 1 < len(text) and text[i+1] == '*':
                    tokens.append(('OP', '**'))
                    i += 2
                else:
                    tokens.append(('SYMBOL', '*'))
                    i += 1
            elif char in ',;':
                tokens.append(('SYMBOL', char))
                i += 1
            elif char.isdigit() or char == '.':
                start = i
                while i < len(text) and (text[i].isdigit() or text[i] == '.'):
                    i += 1
                num_str = text[start:i]
                try:
                    if '.' in num_str:
                        tokens.append(('NUMBER', float(num_str)))
                    else:
                        tokens.append(('NUMBER', int(num_str)))
                except ValueError:
                    raise SyntaxError(f"Invalid number: {num_str}")
            elif char.isalpha() or char == '_':
                start = i
                while i < len(text) and (text[i].isalnum() or text[i] == '_'):
                    i += 1
                tokens.append(('ID', text[start:i]))
            else:
                raise SyntaxError(f"Unexpected character: {char}")
        return tokens

    def parse_program(self, program):
        last_val = None
        # Split by semicolon or newline (but not inside comments)
        raw_statements = re.split(r';|\n', program)
        for stmt in raw_statements:
            stmt = stmt.strip()
            if not stmt:
                continue
            stmt = re.split(r'#', stmt)[0].strip()
            if not stmt:
                continue

            tokens = self.tokenize(stmt)
            last_val = self._execute_statement(tokens)
        return last_val

    def _execute_statement(self, tokens):
        if len(tokens) >= 2 and tokens[0][0] == 'ID' and tokens[1][1] == '=':
            name = tokens[0][1]
            if not (name[0].isalpha() or name[0] == '_'):
                raise SyntaxError(f"Invalid variable name: {name}")
            expr_tokens = tokens[2:]
            val = self._parse_expression(expr_tokens)
            self.variables[name] = val
            return val
        else:
            return self._parse_expression(tokens)

    def _parse_expression(self, tokens):
        if not tokens:
            raise SyntaxError("Empty expression")
        self.pos = 0
        self.tokens = tokens
        result = self._parse_add_sub()
        while self.pos < len(self.tokens) and self.tokens[self.pos][1] != ';':
             raise SyntaxError("Unexpected token in expression")
        return result

    def _peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _consume(self, expected_type=None, expected_val=None):
        token = self._peek()
        if token is None:
            raise SyntaxError("Unexpected end of input")
        if expected_type and token[0] != expected_type:
            raise SyntaxError(f"Expected {expected_type}, got {token[0]}")
        if expected_val and token[1] != expected_val:
            raise SyntaxError(f"Expected {expected_val}, got {token[1]}")
        self.pos += 1
        return token

    def _parse_add_sub(self):
        node = self._parse_mul_div_mod()
        while True:
            token = self._peek()
            if token and token[0] == 'SYMBOL' and token[1] in ('+', '-'):
                op = self._consume()[1]
                right = self._parse_mul_div_mod()
                if isinstance(node, (int, float)) and isinstance(right, (int, float)):
                    if op == '+': node += right
                    else: node -= right
                else: raise SyntaxError("Invalid operand")
            else:
                break
        return node

    def _parse_mul_div_mod(self):
        node = self._parse_unary()
        while True:
            token = self._peek()
            if token and token[0] == 'SYMBOL' and token[1] in ('*', '/', '%'):
                op = self._consume()[1]
                right = self._parse_unary()
                try:
                    if op == '*': node *= right
                    elif op == '/': 
                        if right == 0: raise ZeroDivisionError("division by zero")
                        node /= right
                    else: # modulo
                        if right == 0: raise ZeroDivisionError("modulo by zero")
                        node %= right
                except ZeroDivisionError as e:
                    raise e
                except Exception:
                    raise SyntaxError("Arithmetic error")
            else:
                break
        return node

    def _parse_unary(self):
        token = self._peek()
        if token and token[0] == 'SYMBOL' and token[1] in ('+', '-'):
            op = self._consume()[1]
            operand = self._parse_exponent()
            if op == '-': return -operand
            return operand
        return self._parse_exponent()

    def _parse_exponent(self):
        node = self._parse_primary()
        while True:
            token = self._peek()
            if token and token[1] == '**':
                self._consume()
                right = self._parse_exponent() 
                try:
                    node = node ** right
                except ZeroDivisionError:
                    raise ZeroDivisionError("division by zero")
                except Exception:
                    raise SyntaxError("Arithmetic error")
            else:
                break
        return node

    def _parse_primary(self):
        token = self._peek()
        if token is None:
            raise SyntaxError("Unexpected end of expression")

        if token[0] == 'NUMBER':
            return self._consume()[1]

        if token[0] == 'ID':
            name = self._consume()[1]
            if self._peek() and self._peek()[1] == '(':
                self._consume('SYMBOL', '(')
                args = []
                if self._peek() and self._peek()[1] != ')':
                    while True:
                        args.append(self._parse_expression_logic())
                        next_token = self._peek()
                        if next_token and next_token[1] == ',':
                            self._consume('SYMBOL', ',')
                        else:
                            break
                if not (self._peek() and self._peek()[1] == ')'):
                    raise SyntaxError("Expected ')'")
                self._consume('SYMBOL', ')')
                return self._call_function(name, args)
            else:
                if name not in self.variables:
                    raise NameError(f"name '{name}' is not defined")
                return self.variables[name]

        if token and token[1] == '(':
            self._consume('SYMBOL', '(')
            val = self._parse_expression_logic()
            self._consume('SYMBOL', ')')
            return val

        raise SyntaxError(f"Unexpected token: {token}")

    def _call_function(self, name, args):
        if name == 'abs':
            if len(args) != 1: raise SyntaxError("abs() requires exactly 1 argument")
            return abs(args[0])
        elif name == 'min':
            if not args: raise SyntaxError("min() requires at least one argument")
            return min(args)
        elif name == 'max':
            if not args: raise SyntaxError("max() requires at least one argument")
            return max(args)
        else:
            raise NameError(f"name '{name}' is not defined")

    def _parse_expression_logic(self):
        return self._parse_add_sub()

def calistir(program: str):
    calc = Calculator()
    try:
        return calc.parse_program(program)
    except (SyntaxError, NameError, ZeroDivisionError) as e:
        raise e
